import re, pandas as pd

def money(s):
    s = str(s).lower().replace('đ', '').replace(' ', '')
    try:
        if 'tr' in s:
            a, b = s.split('tr', 1)
            return float(a.replace(',', '.') or 0) * 1e6 + (float(b) * 1000 if b else 0)
        if s.endswith('k'):
            return float(s[:-1].replace(',', '.')) * 1e3
        return float(re.sub(r'[^0-9.\-]', '', s.replace(',', '')).replace('.', ''))
    except ValueError:
        return float('nan')

def between(dt, a, b):
    return (dt >= pd.Timestamp(a)) & (dt < pd.Timestamp(b) + pd.Timedelta(days=1))

def to_date(x):
    x = str(x)
    if x.isdigit():
        return pd.Timestamp('1899-12-30') + pd.Timedelta(days=int(x))
    return pd.to_datetime(re.sub(r'\s*thg\s*|\s+', '/', x), format='%d/%m/%Y', errors='coerce')

